/**
 * embed-contexts.cjs — Read JSON-LD context files and generate a TypeScript
 * module exporting them as typed objects.
 *
 * This eliminates the createRequire + require("*.json") pattern, making the
 * package compatible with bundlers (esbuild, webpack, rollup).
 *
 * Reads from two locations:
 *   1. src/contexts/            — human-maintained base contexts (W3C, OpenCred)
 *   2. src/contexts/external/   — auto-generated by schema-engine's
 *                                 fetch-and-embed-schemas.mjs for credential
 *                                 schemas bundled at release build time
 *
 * Runs as part of the build step, before tsc.
 */

const fs = require("fs");
const path = require("path");

const baseDir = path.resolve(__dirname, "..", "src", "contexts");
const externalDir = path.join(baseDir, "external");
const outFile = path.resolve(__dirname, "..", "src", "context-data.ts");

function listJsonFiles(dir) {
  if (!fs.existsSync(dir)) {
    return [];
  }
  return fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".json"))
    .sort()
    .map((f) => path.join(dir, f));
}

const baseFiles = listJsonFiles(baseDir);
const externalFiles = listJsonFiles(externalDir);
const allFiles = [...baseFiles, ...externalFiles];

if (allFiles.length === 0) {
  console.error("[embed-contexts] No JSON files found in", baseDir, "or", externalDir);
  process.exit(1);
}

const lines = [
  "// Auto-generated by scripts/embed-contexts.cjs — do not edit manually.",
  "// Edit the JSON files in src/contexts/ (or src/contexts/external/ for",
  "// build-generated credential contexts) and re-run the build.",
  "",
];

const seen = new Set();
for (const filePath of allFiles) {
  const file = path.basename(filePath);
  const content = fs.readFileSync(filePath, "utf-8");
  // Validate it's valid JSON
  JSON.parse(content);
  // Convert filename to camelCase: "credentials-v2.json" → "credentialsV2"
  const name = file
    .replace(".json", "")
    .replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
  if (seen.has(name)) {
    console.error(
      `[embed-contexts] Duplicate export name "${name}" from ${filePath} — rename the source file`,
    );
    process.exit(1);
  }
  seen.add(name);
  lines.push(`export const ${name}: Record<string, unknown> = ${content.trim()};`);
  lines.push("");
}

fs.writeFileSync(outFile, lines.join("\n"));
console.log(
  `[embed-contexts] Generated ${outFile} with ${allFiles.length} contexts ` +
    `(${baseFiles.length} base, ${externalFiles.length} external)`,
);
